from __future__ import annotations

import hashlib
import json
import os
import threading
import unicodedata
import uuid
from dataclasses import dataclass, replace
from pathlib import Path
from urllib.parse import urlsplit

REFERENCE_EPOCH = 978_307_200
CAPACITY = 100
MAX_TEXT_BYTES = 1_000_000
MAX_AGE = 24 * 3600

SKIPPED_TYPES = {
    "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
    "com.agilebits.onepassword", "de.petermaurer.TransientPasteboardType", "com.typeit4me.clipping",
    "Pasteboard generator type", "ExcludeClipboardContentFromMonitorProcessing",
}


OPT_OUT_FLAGS = ("CanIncludeInClipboardHistory", "CanUploadToCloudClipboard")


def should_capture(types: list[str]) -> bool:
    return bool(types) and not any(t in SKIPPED_TYPES for t in types)


def opted_out(types: list[str], read_flag) -> bool:
    return any(name in types and read_flag(name) == 0 for name in OPT_OUT_FLAGS)


def kind_of(text: str) -> str:
    trimmed = text.strip()
    if not trimmed or any(c.isspace() for c in trimmed):
        return "text"
    parts = urlsplit(trimmed)
    return "url" if parts.scheme.lower() in ("http", "https") and parts.hostname else "text"


def fingerprint(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def thumbnail_name(image: str) -> str:
    return image.replace(".png", "-thumb.png")


def _fold(text: str) -> str:
    return "".join(c for c in unicodedata.normalize("NFD", text) if unicodedata.category(c) != "Mn").lower()


@dataclass
class ClipItem:
    id: str
    kind: str
    text: str | None
    image: str | None
    fingerprint: str
    copied_at: float
    pinned: bool = False

    @staticmethod
    def new(kind: str, text: str | None, image: str | None, fingerprint: str, copied_at: float,
            item_id: str | None = None) -> "ClipItem":
        return ClipItem((item_id or str(uuid.uuid4())).upper(), kind, text, image, fingerprint, copied_at)

    @property
    def image_files(self) -> list[str]:
        return [self.image, thumbnail_name(self.image)] if self.image else []

    def as_json(self) -> dict:
        return {"id": self.id, "kind": self.kind, "text": self.text, "image": self.image,
                "copied_at": self.copied_at, "pinned": self.pinned}


class History:
    def __init__(self, items: list[ClipItem] | None = None) -> None:
        self.items = items or []

    def contains(self, fp: str) -> bool:
        return any(i.fingerprint == fp for i in self.items)

    def insert(self, item: ClipItem) -> list[ClipItem]:
        for index, existing in enumerate(self.items):
            if existing.fingerprint == item.fingerprint:
                self.items.pop(index)
                self.items.insert(0, replace(existing, copied_at=item.copied_at))
                return []
        self.items.insert(0, item)
        evicted: list[ClipItem] = []
        while len(self.items) > CAPACITY:
            last = next((i for i in range(len(self.items) - 1, -1, -1) if not self.items[i].pinned), None)
            if last is None:
                break
            evicted.append(self.items.pop(last))
        return evicted

    def toggle_pin(self, item_id: str) -> None:
        for item in self.items:
            if item.id == item_id:
                item.pinned = not item.pinned

    def remove(self, item_id: str) -> ClipItem | None:
        for index, item in enumerate(self.items):
            if item.id == item_id:
                return self.items.pop(index)
        return None

    def clear_unpinned(self) -> list[ClipItem]:
        removed = [i for i in self.items if not i.pinned]
        self.items = [i for i in self.items if i.pinned]
        return removed

    def expire(self, now: float, max_age: float = MAX_AGE) -> list[ClipItem]:
        cutoff = now - max_age
        removed = [i for i in self.items if not i.pinned and i.copied_at < cutoff]
        if removed:
            self.items = [i for i in self.items if i.pinned or i.copied_at >= cutoff]
        return removed

    def visible(self, query: str) -> list[ClipItem]:
        needle = _fold(query.strip())
        matched = self.items if not needle else [i for i in self.items if i.text is not None and needle in _fold(i.text)]
        return [i for i in matched if i.pinned] + [i for i in matched if not i.pinned]


def default_directory() -> Path:
    from wisp.serve.store import data_dir
    return data_dir() / "clipboard"


class ClipboardStore:
    def __init__(self, directory: Path | None = None) -> None:
        self.directory = directory or default_directory()
        self.last_recovery_note: str | None = None
        self._lock = threading.Lock()

    @property
    def file(self) -> Path:
        return self.directory / "history.json"

    @property
    def bad(self) -> Path:
        return self.directory / "history.json.bad"

    def load(self) -> History:
        with self._lock:
            if not self.file.exists():
                return History()
            try:
                raw = json.loads(self.file.read_text("utf-8"))
                items = [ClipItem(str(i["id"]).upper(), i["kind"], i.get("text"), i.get("image"), i["fingerprint"],
                                  float(i["copiedAt"]) + REFERENCE_EPOCH, bool(i.get("pinned", False)))
                         for i in raw["items"]]
                if any(i.kind not in ("text", "url", "image") for i in items):
                    raise ValueError("kind")
                return History(items)
            except (OSError, ValueError, KeyError, TypeError):
                self.bad.unlink(missing_ok=True)
                try:
                    os.replace(self.file, self.bad)
                except OSError:
                    pass
                self.last_recovery_note = f"o histórico de copiados estava corrompido; guardei uma cópia em {self.bad}"
                return History()

    def save(self, history: History) -> None:
        def number(value: float):
            seconds = value - REFERENCE_EPOCH
            return int(seconds) if seconds == int(seconds) else seconds

        items = []
        for i in history.items:
            entry = {"copiedAt": number(i.copied_at), "fingerprint": i.fingerprint, "id": i.id, "kind": i.kind,
                     "pinned": i.pinned}
            if i.text is not None:
                entry["text"] = i.text
            if i.image is not None:
                entry["image"] = i.image
            items.append(entry)
        body = json.dumps({"items": items}, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        with self._lock:
            self.directory.mkdir(parents=True, exist_ok=True)
            temporary = self.directory / f".history.json.{uuid.uuid4().hex}.tmp"
            temporary.write_text(body.replace("/", "\\/"), "utf-8")
            os.replace(temporary, self.file)

    def write_image(self, png: bytes, thumbnail: bytes, item_id: str) -> str:
        name = f"{item_id.upper()}.png"
        with self._lock:
            self.directory.mkdir(parents=True, exist_ok=True)
            (self.directory / name).write_bytes(png)
            (self.directory / thumbnail_name(name)).write_bytes(thumbnail)
        return name

    def delete_files(self, items: list[ClipItem]) -> None:
        with self._lock:
            for name in (n for i in items for n in i.image_files):
                (self.directory / name).unlink(missing_ok=True)

    def path_of(self, name: str) -> Path | None:
        if not name or name != Path(name).name or name.startswith("."):
            return None
        return self.directory / name
